// Use existing system downloaders; package setup belongs in the downloaded script.
const char *UBUNTU_BOOTSTRAP = R"CK(set -e; f=$(mktemp); trap 'rm -f "$f"' EXIT; curl -fsSL "$1" -o "$f" || wget -qO "$f" "$1" || python3 -c 'import sys,urllib.request;urllib.request.urlretrieve(sys.argv[1],sys.argv[2])' "$1" "$f" || { apt-get -o DPkg::Lock::Timeout=600 -y install curl ca-certificates && curl -fsSL "$1" -o "$f" || exit 1; }; test -s "$f"; /bin/bash "$f")CK";
